"""The mathematical bridge from unstructured news to the sizing engine.The problem this module solves------------------------------A news event ("first-choice keeper ruled out") changes two distinct quantities,and treating them as one is the loophole that destroys bankrolls:#. **The location of the probability estimate.** The team is now less likely to   win. This is the ``probability_shift_percentage``.#. **The confidence in that estimate.** A verified club announcement moves the   estimate and leaves it sharp. An unsourced social-media rumour moves it and   leaves it *blurry*. This is the ``uncertainty_penalty``.A system that models only the first will happily stake full size on a rumour,because a shifted point estimate looks exactly as trustworthy as a verifiedone. Modelling the second is what makes rumour-driven volatility survivable.Why the uncertainty penalty is a variance multiplier---------------------------------------------------In the mean-variance (second-order) approximation of expected log wealth, thegrowth-optimal staked fraction of a binary bet is::    f* = mu / sigma^2where ``mu = p*b - q`` is the per-unit edge and ``sigma^2 = p*q*o^2`` is theper-unit variance of the return. Inflating the variance by a factor ``lambda``therefore divides the optimal stake by exactly ``lambda``::    f*_lambda = mu / (lambda * sigma^2) = f* / lambdaSo an ``uncertainty_penalty`` of 2.0 halves the stake, 4.0 quarters it, and acompletely unsourced rumour with a penalty of 5.0 reduces it to a fifth. Thepenalty is not a fudge factor bolted onto the output: it is the exactmean-variance-equivalent of saying "I am less sure than my point estimatesuggests", and the stake reduction falls out of the mathematics.Why not "average over a posterior" instead------------------------------------------Because it provably does nothing here. Expected log wealth for a binary bet,``g(f, p) = p*log(1 + f*b) + (1 - p)*log(1 - f)``, is **linear in p**.Integrating it over any posterior on ``p`` returns the posterior *mean* andleaves the optimal ``f`` unchanged. Numerical quadrature over parameteruncertainty is therefore wasted computation for this objective. The twodefensible mechanisms are a quantile (robust) criterion on ``p`` or a variancepenalty on the sizing, and this module implements the latter.Why shifts compose in logit space---------------------------------Naive addition of probability shifts can push a probability outside ``[0, 1]``(three independent "-40%" alerts on a ``p = 0.5`` selection would yield anegative probability). Composing in log-odds space is closed on ``(0, 1)``,order-independent, and monotone, so any number of modifiers can be applied inany sequence and still produce a valid probability. See:func:`compose_modifiers`."""from __future__ import annotationsimport mathfrom datetime import UTC, datetime, timedeltafrom enum import StrEnumfrom typing import Annotated, Final, Selffrom pydantic import (    BaseModel,    ConfigDict,    Field,    computed_field,    field_validator,    model_validator,)from betdoc.domain.intelligence.account_models import SportType, utc_now__all__ = [    "MAX_UNCERTAINTY_PENALTY",    "EntityResolutionTags",    "LiveNewsAlert",    "NewsCategory",    "ProbabilityModifier",    "compose_modifiers",    "credibility_to_uncertainty_penalty",    "logit",    "sigmoid",]_PROBABILITY_FLOOR: Final[float] = 1e-6_PROBABILITY_CEILING: Final[float] = 1.0 - 1e-6MAX_UNCERTAINTY_PENALTY: Final[float] = 10.0"""Hard ceiling on the composed variance multiplier.Beyond a tenfold variance inflation the recommended stake is already insiderounding noise, so an unbounded penalty adds no protection while making thenumber hard to reason about in a post-mortem."""_CREDIBILITY_PENALTY_SLOPE: Final[float] = 4.0"""Calibration constant mapping credibility to penalty.``lambda = 1 + slope * (1 - credibility)``. A verified announcement(credibility 1.0) attracts no penalty; a bare rumour (credibility 0.1) attracts``1 + 4 * 0.9 = 4.6``, cutting the stake to roughly 22% of nominal. Fit thisagainst realized CLV on news-driven bets before trusting it at size."""_DECAY_SHAPE: Final[float] = 3.0"""Exponential decay constant expressed in units of the impact duration.``tau = duration / 3`` leaves about 5% of the effect at ``t = duration``, sothe modifier fades smoothly rather than switching off at a cliff edge. A cliffwould make sizing discontinuous in time, which produces the pathologicalbehaviour of a bet being refused at 59 seconds and authorised at full size at61 seconds."""_STRICT: Final[ConfigDict] = ConfigDict(    frozen=True,    extra="forbid",    validate_default=True,    revalidate_instances="never",    str_strip_whitespace=True,)Probability = Annotated[float, Field(gt=0.0, lt=1.0)]Credibility = Annotated[float, Field(ge=0.0, le=1.0)]def logit(probability: float) -> float:    """Log-odds of a probability, clamped away from the asymptotes."""    clamped = min(max(probability, _PROBABILITY_FLOOR), _PROBABILITY_CEILING)    return math.log(clamped / (1.0 - clamped))def sigmoid(log_odds: float) -> float:    """Inverse of :func:`logit`. Always returns a value strictly in ``(0, 1)``."""    if log_odds >= 0.0:        value = 1.0 / (1.0 + math.exp(-log_odds))    else:        exponent = math.exp(log_odds)        value = exponent / (1.0 + exponent)    return min(max(value, _PROBABILITY_FLOOR), _PROBABILITY_CEILING)def credibility_to_uncertainty_penalty(    credibility: float, *, slope: float = _CREDIBILITY_PENALTY_SLOPE) -> float:    """Map source credibility onto a variance multiplier.    Monotonically decreasing in credibility, equal to exactly 1.0 for a fully    verified source so a trusted announcement is not penalised at all.    """    if not 0.0 <= credibility <= 1.0:        msg = f"credibility must lie in [0, 1], got {credibility!r}"        raise ValueError(msg)    return min(1.0 + slope * (1.0 - credibility), MAX_UNCERTAINTY_PENALTY)class NewsCategory(StrEnum):    """Taxonomy of market-moving events, ordered by typical magnitude."""    INJURY = "injury"    LINEUP_CONFIRMED = "lineup_confirmed"    SUSPENSION = "suspension"    TRANSFER = "transfer"    WEATHER = "weather"    VENUE_CHANGE = "venue_change"    MANAGERIAL_CHANGE = "managerial_change"    REFEREE_APPOINTMENT = "referee_appointment"    MARKET_RUMOUR = "market_rumour"    OTHER = "other"    @property    def is_verifiable_fact(self) -> bool:        """Whether the category is normally an announcement rather than a claim.        Verifiable categories still carry their source's credibility; this only        marks which categories *can* reach credibility 1.0 at all.        """        return self in (            NewsCategory.LINEUP_CONFIRMED,            NewsCategory.SUSPENSION,            NewsCategory.VENUE_CHANGE,            NewsCategory.REFEREE_APPOINTMENT,        )class EntityResolutionTags(BaseModel):    """Resolution of free-text news onto our canonical identifiers.    This is the join key between the news pipeline and the odds pipeline, and    it is the highest-risk model in the intelligence layer. A wrong    ``fixture_id`` does not produce a slightly wrong probability, it applies a    keeper injury from one match to the odds of a completely different one.    ``resolution_confidence`` therefore exists and must be consulted: the    advisor is expected to discard low-confidence resolutions entirely rather    than acting on a plausible guess.    """    model_config = _STRICT    fixture_id: str | None = Field(default=None, max_length=128)    team_id: str | None = Field(default=None, max_length=128)    opponent_team_id: str | None = Field(default=None, max_length=128)    player_name: str | None = Field(default=None, max_length=128)    player_id: str | None = Field(default=None, max_length=128)    league_id: str | None = Field(default=None, max_length=128)    sport_type: SportType = SportType.OTHER    affected_market_keys: tuple[str, ...] = Field(        default=(),        description=(            "Markets this event plausibly moves. An empty tuple means "            "'unknown', which the advisor treats as 'all markets on the "            "fixture' and therefore as strictly more conservative."        ),    )    resolution_confidence: Credibility = Field(        default=0.0,        description="Confidence that these identifiers are the correct ones.",    )    @model_validator(mode="after")    def _must_resolve_something_actionable(self) -> Self:        """An unresolved alert cannot be acted on and must not be silently kept.        Without at least a fixture or a team there is no way to know which odds        to modify, and a modifier applied to nothing is dead weight that makes        the audit trail misleading.        """        if self.fixture_id is None and self.team_id is None:            msg = (                "entity resolution must yield at least a fixture_id or a "                "team_id; an unresolvable alert is not actionable"            )            raise ValueError(msg)        if self.player_id is not None and self.player_name is None:            msg = "player_id supplied without player_name, which blocks audit"            raise ValueError(msg)        return self    @property    def is_reliable(self) -> bool:        """Whether the resolution is trustworthy enough to act on."""        return self.resolution_confidence >= 0.80    def affects_market(self, market_key: str) -> bool:        """Whether this event should modify a given market.        Unknown scope returns ``True``: applying an uncertainty penalty too        widely costs a little expected growth, while applying it too narrowly        leaves a genuinely mispriced market fully staked.        """        return not self.affected_market_keys or market_key in self.affected_market_keysclass LiveNewsAlert(BaseModel):    """A single inbound news item, resolved but not yet quantified.    Deliberately carries the ``raw_text`` alongside the resolution. When a    recommendation is questioned weeks later, the original wording is the only    thing that can settle whether the evaluator interpreted it correctly.    """    model_config = _STRICT    alert_id: str = Field(min_length=1, max_length=128)    timestamp: datetime = Field(description="When the news was published, not when we ingested it.")    received_at: datetime = Field(default_factory=utc_now)    source_name: str = Field(min_length=1, max_length=128)    source_credibility: Credibility = Field(        description=(            "Calibrated per source from historical accuracy. An official club "            "channel approaches 1.0; an anonymous aggregator sits near 0.2. "            "This drives the uncertainty penalty, so a miscalibrated source "            "score directly mis-sizes every bet it touches."        )    )    category: NewsCategory = NewsCategory.OTHER    raw_text: str = Field(min_length=1, max_length=8_192)    entities: EntityResolutionTags    is_rumour: bool = Field(        default=False,        description="Explicitly unconfirmed. Forces a floor on the penalty.",    )    @field_validator("timestamp", "received_at", mode="after")    @classmethod    def _require_timezone(cls, value: datetime) -> datetime:        if value.tzinfo is None:            msg = "datetime must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @model_validator(mode="after")    def _rumours_cannot_claim_high_credibility(self) -> Self:        """Block the contradiction of a "highly credible unconfirmed rumour".        Left unchecked, a mislabelled source score on a rumour would suppress        the uncertainty penalty precisely where it is most needed.        """        if self.is_rumour and self.source_credibility > 0.60:            msg = (                "an explicit rumour cannot carry credibility above 0.60; "                f"got {self.source_credibility!r}"            )            raise ValueError(msg)        if self.category.is_verifiable_fact and self.is_rumour and self.source_credibility > 0.40:            msg = "an unconfirmed report of a verifiable fact is low credibility"            raise ValueError(msg)        return self    @property    def ingest_latency_seconds(self) -> float:        """Publication to ingestion. Large values mean the market moved first."""        return (self.received_at - self.timestamp).total_seconds()    @property    def is_actionable(self) -> bool:        """Whether the alert is resolved reliably enough to modify prices."""        return self.entities.is_reliable and self.source_credibility > 0.0    def baseline_uncertainty_penalty(self) -> float:        """Penalty implied by credibility alone, before impact assessment.        Serves as the floor an evaluator may not undercut, so a model that is        confident about the *magnitude* of a rumour still cannot claim to be        confident about its *truth*.        """        penalty = credibility_to_uncertainty_penalty(self.source_credibility)        return max(penalty, 2.0) if self.is_rumour else penaltyclass ProbabilityModifier(BaseModel):    """The quantified, time-decaying output of one news event.    Three orthogonal effects, each with its own decay:    * ``probability_shift_percentage`` relocates the estimate.    * ``uncertainty_penalty`` widens it, dividing the Kelly stake by the same      factor.    * ``impact_duration_seconds`` bounds how long either applies.    Both effects decay exponentially towards neutral (shift towards 0.0,    penalty towards 1.0) with a time constant of one third of the declared    duration. Decay is continuous by design: a step function would make the    authorised stake discontinuous in time, so the same bet could be refused    outright one second and authorised at full size the next.    """    model_config = _STRICT    modifier_id: str = Field(min_length=1, max_length=128)    source_alert_id: str = Field(min_length=1, max_length=128)    entities: EntityResolutionTags    created_at: datetime = Field(default_factory=utc_now)    probability_shift_percentage: float = Field(        ge=-0.95,        le=0.95,        description=(            "Relative change to the fair probability. -0.05 means a 5% relative "            "reduction, so p = 0.40 becomes 0.38. Applied through log-odds so "            "the result is always a valid probability regardless of magnitude."        ),    )    uncertainty_penalty: float = Field(        gt=1.0,        le=MAX_UNCERTAINTY_PENALTY,        description=(            "Variance multiplier, strictly above 1.0. Because the mean-variance "            "optimum is f* = mu / sigma^2, this divides the recommended stake by "            "exactly this factor. A rumour at 4.0 therefore stakes a quarter of "            "nominal, which is what stops rumour-driven volatility from "            "compounding into a drawdown."        ),    )    impact_duration_seconds: float = Field(        gt=0.0,        le=604_800.0,        description="Effect lifetime. Capped at one week.",    )    confidence: Credibility = Field(        default=0.5, description="Evaluator confidence in the quantification."    )    rationale: str = Field(        default="",        max_length=1_024,        description="Human-readable basis, surfaced in the recommendation.",    )    @field_validator("created_at", mode="after")    @classmethod    def _require_timezone(cls, value: datetime) -> datetime:        if value.tzinfo is None:            msg = "created_at must be timezone-aware"            raise ValueError(msg)        return value.astimezone(UTC)    @model_validator(mode="after")    def _penalty_must_reflect_confidence(self) -> Self:        """A low-confidence quantification cannot carry a near-neutral penalty.        The failure this prevents: an evaluator that is unsure of its own        output but reports ``uncertainty_penalty = 1.01``, which would let a        guess through at effectively full stake.        """        if self.confidence < 0.30 and self.uncertainty_penalty < 2.0:            msg = (                f"confidence {self.confidence!r} is too low to justify an "                f"uncertainty penalty of {self.uncertainty_penalty!r}; a "                "low-confidence estimate must widen the distribution"            )            raise ValueError(msg)        return self    @computed_field  # type: ignore[prop-decorator]    @property    def expires_at(self) -> datetime:        """Instant beyond which the modifier is inert."""        return self.created_at + timedelta(seconds=self.impact_duration_seconds)    def decay_factor(self, *, now: datetime | None = None) -> float:        """Remaining strength in ``[0, 1]``, exponential with ``tau = D / 3``.        Returns exactly 0.0 once the declared duration has elapsed, so an        expired modifier cannot silently persist.        """        elapsed = ((now or utc_now()) - self.created_at).total_seconds()        if elapsed <= 0.0:            return 1.0        if elapsed >= self.impact_duration_seconds:            return 0.0        tau = self.impact_duration_seconds / _DECAY_SHAPE        return math.exp(-elapsed / tau)    def is_active(self, *, now: datetime | None = None) -> bool:        return self.decay_factor(now=now) > 0.0    def effective_shift(self, *, now: datetime | None = None) -> float:        """Time-decayed probability shift. Decays towards zero."""        return self.probability_shift_percentage * self.decay_factor(now=now)    def effective_penalty(self, *, now: datetime | None = None) -> float:        """Time-decayed variance multiplier. Decays towards exactly 1.0.        Decaying the *excess* above 1.0 rather than the penalty itself keeps        the neutral element neutral: an expired modifier multiplies variance by        1.0 and therefore leaves the stake untouched.        """        excess = self.uncertainty_penalty - 1.0        return 1.0 + excess * self.decay_factor(now=now)    def logit_delta(self, base_probability: float, *, now: datetime | None = None) -> float:        """Additive log-odds displacement for this modifier.        Computed as ``logit(p * (1 + s)) - logit(p)`` on the decayed shift.        Expressing the effect as a log-odds delta is what makes composition        safe: deltas add, the sum passes through the sigmoid exactly once, and        the result is guaranteed to stay strictly inside ``(0, 1)`` no matter        how many modifiers are stacked or in what order.        """        shift = self.effective_shift(now=now)        if shift == 0.0:            return 0.0        target = min(            max(base_probability * (1.0 + shift), _PROBABILITY_FLOOR),            _PROBABILITY_CEILING,        )        return logit(target) - logit(base_probability)    def applies_to(self, *, fixture_id: str, market_key: str) -> bool:        """Scope test against a specific fixture and market."""        if self.entities.fixture_id is not None:            if self.entities.fixture_id != fixture_id:                return False        return self.entities.affects_market(market_key)def compose_modifiers(    base_probability: float,    modifiers: tuple[ProbabilityModifier, ...],    *,    now: datetime | None = None,) -> tuple[float, float]:    """Combine many modifiers into one probability and one variance multiplier.    Composition rules, and the reason for each:    * **Shifts add in log-odds space.** Closed on ``(0, 1)``, monotone, and      order-independent. Adding raw percentage shifts is none of those things      and can produce a negative probability from three plausible alerts.    * **Penalties multiply.** Variance multipliers compose multiplicatively by      definition, so two independent doublings of uncertainty give a fourfold      inflation and therefore a quarter stake. The product is capped at      :data:`MAX_UNCERTAINTY_PENALTY`, because past a tenfold inflation the      stake is already negligible and an uncapped figure only makes the audit      trail harder to read.    Args:        base_probability: Fair probability before news, strictly in ``(0, 1)``.        modifiers: Modifiers already filtered for scope. Expired ones are            skipped, so passing a stale list is safe.        now: Evaluation instant, injected for determinism in tests.    Returns:        ``(adjusted_probability, composed_uncertainty_penalty)``. The        probability is always strictly inside ``(0, 1)``, and the penalty is        always at least 1.0.    Raises:        ValueError: ``base_probability`` is not strictly inside ``(0, 1)``.    """    if not 0.0 < base_probability < 1.0:        msg = f"base_probability must lie strictly in (0, 1), got {base_probability!r}"        raise ValueError(msg)    total_delta = 0.0    penalty = 1.0    for modifier in modifiers:        if not modifier.is_active(now=now):            continue        total_delta += modifier.logit_delta(base_probability, now=now)        penalty *= modifier.effective_penalty(now=now)    adjusted = sigmoid(logit(base_probability) + total_delta)    return adjusted, min(max(penalty, 1.0), MAX_UNCERTAINTY_PENALTY)